// GENERATED by cruftfree-codegen-angular. DO NOT EDIT.
//
// A map basemap drawn from an installed offline package (`basemaps(offline(Site, key, "style.json"))`).
// The style document is a member of the installed copy; every address it names -- a source's
// `url`, `tiles` and `data`, the `glyphs` template and the `sprite` -- must be a path inside the
// package, and is rewritten to this adapter's `localUrl(path)`: `cruftfree-package://<id>/<path>`,
// an address only the protocol handler registered here answers (`addProtocol`). The handler reads
// the member from the copy registered under `<id>` and answers nothing for a request whose path,
// each segment percent-decoded once, leaves the package or names no member. A style naming any
// other address is refused whole; a text layer's fonts are written as literal names, so the
// engine never builds a glyph address from the data. Nothing of a package basemap reaches the
// network. The rule is the shared one, held to the shared tables by the app's package map spec.

import { addProtocol } from 'maplibre-gl';

import { bytesOf, type AppBytes } from '../bytes';

/** The protocol of the addresses `localUrl` writes. */
export const PACKAGE_URL_SCHEME = 'cruftfree-package';

/** Why a package style was refused. */
export const PACKAGE_STYLE_REFUSED = {
  reference: 'reference',
  font: 'font',
  shape: 'shape',
} as const;
export type PackageStyleRefusal = (typeof PACKAGE_STYLE_REFUSED)[keyof typeof PACKAGE_STYLE_REFUSED];

/** A package style the rule refuses: *reason* says why. */
export class PackageStyleRefused extends Error {
  constructor(
    readonly reason: PackageStyleRefusal,
    message: string,
  ) {
    super(message);
    this.name = 'PackageStyleRefused';
  }
}

/** The installed copy of a package a basemap draws from: its member paths and a reader of each. */
export interface UiPackageCopy {
  readonly members: readonly string[];
  /** The bytes of the member *path*, or `null` when the copy holds none. */
  read(path: string): Promise<AppBytes | null>;
}

/**
 * A map's `offline(Package, key, "style")` basemap: switched to by *name* (the package's name),
 * drawn from the copy of *packageName* installed under *key* (the catalogue key text), its style
 * the member *style*.
 */
export interface UiPackageBasemap {
  readonly name: string;
  readonly packageName: string;
  readonly key: string;
  readonly style: string;
}

/**
 * What reads an app's installed packages: the app-state service's `cruftfree.ui` functions, the one
 * catalogue every client reads (`installedPackage`, `packageMember`).
 */
export interface UiPackageReader {
  installedPackage(packageName: string, key: string): Promise<{ readonly members: readonly string[] } | null>;
  packageMember(packageName: string, key: string, path: string): Promise<AppBytes | null>;
}

/** The copy *basemap* draws from, read through *reader*; `null` when none is installed. */
export async function openPackageCopy(reader: UiPackageReader, basemap: UiPackageBasemap): Promise<UiPackageCopy | null> {
  const entry = await reader.installedPackage(basemap.packageName, basemap.key);
  if (entry === null) {
    return null;
  }
  return {
    members: entry.members,
    read: (path: string) => reader.packageMember(basemap.packageName, basemap.key, path),
  };
}

const MAX_REFERENCE = 1024;
const FORBIDDEN_PATH_CHARACTERS = new Set([':', '\\', '?', '#', '%']);
const TEMPLATE_PLACEHOLDERS: ReadonlySet<string> = new Set(['fontstack', 'prefix', 'quadkey', 'range', 'ratio', 'x', 'y', 'z']);
const PLACEHOLDER = /\{([a-z]+)\}/g;
const SPRITE_INDEX_SUFFIX = '.json';
const LITERAL_OPERATOR = 'literal';

function hasControlCharacter(text: string): boolean {
  for (const character of text) {
    const code = character.codePointAt(0) ?? 0;
    if (code < 0x20 || code === 0x7f) {
      return true;
    }
  }
  return false;
}

/** *reference* when it is a path inside a package, else `null`. */
export function packageLocalPath(reference: string): string | null {
  if (reference.length === 0 || reference.length > MAX_REFERENCE || reference.startsWith('/')) {
    return null;
  }
  if (hasControlCharacter(reference) || [...reference].some((character) => FORBIDDEN_PATH_CHARACTERS.has(character))) {
    return null;
  }
  if (reference.split('/').some((segment) => segment === '' || segment === '.' || segment === '..')) {
    return null;
  }
  return reference;
}

/**
 * The member the request *request* (`<scheme>://<id>/<path>`, placeholders filled by the engine)
 * reads from the copy registered as *packageId*, or `null` -- answered with nothing.
 */
export function packageRequestPath(request: string, packageId: string, members: ReadonlySet<string>): string | null {
  const prefix = `${PACKAGE_URL_SCHEME}://${packageId}/`;
  if (!request.startsWith(prefix)) {
    return null;
  }
  let decoded: string;
  try {
    decoded = request
      .slice(prefix.length)
      .split('/')
      .map((segment) => decodeSegment(segment))
      .join('/');
  } catch {
    return null;
  }
  const path = packageLocalPath(decoded);
  return path !== null && members.has(path) ? path : null;
}

/** One segment percent-decoded once; an escape that is no `%XX` stays as written; invalid UTF-8 throws. */
function decodeSegment(segment: string): string {
  return segment.replace(/(?:%[0-9A-Fa-f]{2})+/g, (run) => decodeURIComponent(run));
}

function templatePath(reference: string): string | null {
  const path = packageLocalPath(reference);
  if (path === null) {
    return null;
  }
  const literal = path.replace(PLACEHOLDER, '');
  if (literal.includes('{') || literal.includes('}')) {
    return null;
  }
  for (const match of path.matchAll(PLACEHOLDER)) {
    if (!TEMPLATE_PLACEHOLDERS.has(match[1])) {
      return null;
    }
  }
  return path;
}

function resolved(reference: unknown, members: ReadonlySet<string>, localUrl: (path: string) => string, suffix = ''): string {
  if (typeof reference !== 'string') {
    throw new PackageStyleRefused(PACKAGE_STYLE_REFUSED.reference, `A package style address ${String(reference)} is no text.`);
  }
  const path = templatePath(reference);
  if (path === null) {
    throw new PackageStyleRefused(PACKAGE_STYLE_REFUSED.reference, `The package style address '${reference}' is no path inside the package.`);
  }
  if (path.search(PLACEHOLDER) < 0 && !members.has(`${path}${suffix}`)) {
    throw new PackageStyleRefused(PACKAGE_STYLE_REFUSED.reference, `The package style address '${reference}' names no member of the package.`);
  }
  return localUrl(path);
}

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function safeFontName(name: unknown): boolean {
  if (typeof name !== 'string' || name.length === 0 || name === '.' || name === '..') {
    return false;
  }
  return !hasControlCharacter(name) && !/[/\\%]/.test(name);
}

function literalFonts(layers: unknown): void {
  if (!Array.isArray(layers)) {
    throw new PackageStyleRefused(PACKAGE_STYLE_REFUSED.shape, "A package style's layers are no list.");
  }
  for (const layer of layers) {
    const layout = isObject(layer) ? layer['layout'] : undefined;
    if (!isObject(layout) || !Object.hasOwn(layout, 'text-font')) {
      continue;
    }
    let fonts: unknown = layout['text-font'];
    if (Array.isArray(fonts) && fonts.length === 2 && fonts[0] === LITERAL_OPERATOR) {
      fonts = fonts[1];
    }
    if (!Array.isArray(fonts) || fonts.length === 0 || !fonts.every(safeFontName)) {
      throw new PackageStyleRefused(PACKAGE_STYLE_REFUSED.font, "A package style layer's text-font is no list of plain font names.");
    }
    layout['text-font'] = [LITERAL_OPERATOR, [...fonts]];
  }
}

function rewriteSprite(sprite: unknown, members: ReadonlySet<string>, localUrl: (path: string) => string): unknown {
  if (Array.isArray(sprite)) {
    return sprite.map((entry: unknown) => {
      if (!isObject(entry) || typeof entry['id'] !== 'string') {
        throw new PackageStyleRefused(PACKAGE_STYLE_REFUSED.shape, "A package style's sprite entry is no {id, url}.");
      }
      return { ...entry, url: resolved(entry['url'], members, localUrl, SPRITE_INDEX_SUFFIX) };
    });
  }
  return resolved(sprite, members, localUrl, SPRITE_INDEX_SUFFIX);
}

function rewriteSource(name: string, source: unknown, members: ReadonlySet<string>, localUrl: (path: string) => string): Record<string, unknown> {
  if (!isObject(source)) {
    throw new PackageStyleRefused(PACKAGE_STYLE_REFUSED.shape, `The package style source '${name}' is no object.`);
  }
  const rewritten: Record<string, unknown> = { ...source };
  for (const key of ['url', 'data']) {
    if (key === 'data' && typeof source[key] !== 'string') {
      continue;
    }
    if (Object.hasOwn(source, key)) {
      rewritten[key] = resolved(source[key], members, localUrl);
    }
  }
  if (Object.hasOwn(source, 'urls')) {
    throw new PackageStyleRefused(PACKAGE_STYLE_REFUSED.reference, `The package style source '${name}' names video addresses.`);
  }
  if (Object.hasOwn(source, 'tiles')) {
    const tiles = source['tiles'];
    if (!Array.isArray(tiles) || tiles.length === 0) {
      throw new PackageStyleRefused(PACKAGE_STYLE_REFUSED.shape, `The package style source '${name}' has no list of tiles.`);
    }
    rewritten['tiles'] = tiles.map((tile: unknown) => resolved(tile, members, localUrl));
  }
  return rewritten;
}

/**
 * The package style *document* with every address rewritten through *localUrl*; throws
 * `PackageStyleRefused` for a style that reaches outside the package. *document* is not changed.
 */
export function packageStyle(document: unknown, members: ReadonlySet<string>, localUrl: (path: string) => string): Record<string, unknown> {
  if (!isObject(document) || !isObject(document['sources'])) {
    throw new PackageStyleRefused(PACKAGE_STYLE_REFUSED.shape, 'A package style is no object with sources.');
  }
  const style = structuredClone(document);
  if (Object.hasOwn(style, 'layers')) {
    literalFonts(style['layers']);
  }
  const sources: Record<string, unknown> = {};
  for (const [name, source] of Object.entries(document['sources'])) {
    sources[name] = rewriteSource(name, source, members, localUrl);
  }
  style['sources'] = sources;
  if (Object.hasOwn(document, 'glyphs')) {
    style['glyphs'] = resolved(document['glyphs'], members, localUrl);
  }
  if (Object.hasOwn(document, 'sprite')) {
    style['sprite'] = rewriteSprite(document['sprite'], members, localUrl);
  }
  return style;
}

/** A registered copy: its members and reader, by the id its addresses carry. */
interface RegisteredCopy {
  readonly members: ReadonlySet<string>;
  readonly copy: UiPackageCopy;
}

const registered = new Map<string, RegisteredCopy>();
let nextId = 0;
let protocolAdded = false;

/**
 * Answers one engine request for a package address: the member's bytes, or a failure -- the
 * request resolves nothing -- for an address of no registered copy, a path leaving the package,
 * or a member the copy no longer holds.
 */
export async function packageProtocolAnswer(request: string): Promise<{ data: ArrayBuffer }> {
  const id = /^[^:]+:\/\/([^/]+)\//.exec(request)?.[1];
  const entry = id === undefined ? undefined : registered.get(id);
  const path = entry === undefined || id === undefined ? null : packageRequestPath(request, id, entry.members);
  if (entry === undefined || path === null) {
    throw new Error('A package map address names nothing inside an installed package.');
  }
  const bytes = await entry.copy.read(path);
  if (bytes === null) {
    throw new Error('A package map address names a member the installed copy no longer holds.');
  }
  const data = await bytesOf(bytes);
  return { data: data.buffer };
}

/** A copy registered for one map's basemap: its `localUrl` and the release of its id. */
export interface UiPackageRegistration {
  localUrl(path: string): string;
  release(): void;
}

/** Registers *copy* under a fresh id, adding the protocol handler the first time. */
export function registerPackageCopy(copy: UiPackageCopy): UiPackageRegistration {
  if (!protocolAdded) {
    addProtocol(PACKAGE_URL_SCHEME, (params) => packageProtocolAnswer(params.url));
    protocolAdded = true;
  }
  nextId += 1;
  const id = String(nextId);
  registered.set(id, { members: new Set(copy.members), copy });
  return {
    localUrl: (path: string) => `${PACKAGE_URL_SCHEME}://${id}/${path}`,
    release: () => {
      registered.delete(id);
    },
  };
}

/**
 * Loads the package basemap *basemap*: its installed copy, its style member parsed and rewritten
 * inside the copy. Throws when no copy is installed, the style path is no member, or the rule
 * refuses the style; the registration is released then.
 */
export async function loadPackageBasemap(
  reader: UiPackageReader,
  basemap: UiPackageBasemap,
): Promise<{ document: object; registration: UiPackageRegistration }> {
  const copy = await openPackageCopy(reader, basemap);
  if (copy === null) {
    throw new Error(`The basemap ${basemap.name} draws from a package with no installed copy.`);
  }
  const stylePath = packageLocalPath(basemap.style);
  if (stylePath === null || !copy.members.includes(stylePath)) {
    throw new PackageStyleRefused(PACKAGE_STYLE_REFUSED.reference, `The basemap ${basemap.name}'s style '${basemap.style}' is no member of its package.`);
  }
  const bytes = await copy.read(stylePath);
  if (bytes === null) {
    throw new Error(`The basemap ${basemap.name}'s style is no longer held by its installed copy.`);
  }
  const registration = registerPackageCopy(copy);
  try {
    const parsed: unknown = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(await bytesOf(bytes)));
    return { document: packageStyle(parsed, new Set(copy.members), registration.localUrl), registration };
  } catch (error: unknown) {
    registration.release();
    throw error;
  }
}
